import React, { useState, useCallback, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { SettingsPanel } from './components/SettingsPanel';
import { LightCanvas } from './components/LightCanvas';

const DEFAULT_MODEL = '🍌 Nano Banana Pro';

export type AspectRatio = '1:1' | '16:9' | '9:16' | '4:3' | '3:4';

export interface LightVector {
  start: { x: number; y: number };
  end: { x: number; y: number };
}

export default function App() {
  const [sourceMedia, setSourceMedia] = useState<any>(null);
  const [resultMedia, setResultMedia] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [detectedRatio, setDetectedRatio] = useState<AspectRatio>('1:1');

  // Placement State
  const [activeVector, setActiveVector] = useState<LightVector | null>(null);

  // Settings
  const [model, setModel] = useState(DEFAULT_MODEL);
  const [lightStyle, setLightStyle] = useState('Cinematic');
  const [intensity, setIntensity] = useState(70);
  const [lightColor, setLightColor] = useState('Warm White');

  // Inject global styles for the design system
  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      input[type=range] { -webkit-appearance: none; appearance: none; background: transparent; width: 100%; cursor: pointer; padding: 8px 0; }
      input[type=range]::-webkit-slider-runnable-track { width: 100%; height: 3px; background: #595959; border-radius: 9999px; }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0px 1px 3px rgba(0,0,0,0.5); margin-top: -5.5px; cursor: grab; }
      input[type=range]::-webkit-slider-thumb:active { cursor: grabbing; }
      .dark-scrollbar { scrollbar-width: thin; scrollbar-color: #595959 transparent; }
      .dark-scrollbar::-webkit-scrollbar { width: 6px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: #595959; border-radius: 9999px; }
      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.15s ease-out forwards; }
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; letter-spacing: 0.1px; -webkit-font-smoothing: antialiased; }
    `;
    document.head.appendChild(style);
  }, []);

  const getClosestAspectRatio = (width: number, height: number): AspectRatio => {
    const ratio = width / height;
    const targets: { label: AspectRatio; value: number }[] = [
      { label: '16:9', value: 16 / 9 },
      { label: '4:3', value: 4 / 3 },
      { label: '1:1', value: 1 },
      { label: '3:4', value: 3 / 4 },
      { label: '9:16', value: 9 / 16 },
    ];
    return targets.reduce((prev, curr) => 
      Math.abs(curr.value - ratio) < Math.abs(prev.value - ratio) ? curr : prev
    ).label;
  };

  const handleSelectMedia = async () => {
    setError(null);
    try {
      const media = await Flow.media.select({ filter: 'image' });
      const img = new Image();
      img.onload = () => {
        const ratio = getClosestAspectRatio(img.naturalWidth, img.naturalHeight);
        setDetectedRatio(ratio);
        setSourceMedia(media);
        setResultMedia(null);
        setActiveVector(null);
      };
      img.src = `data:${media.mimeType};base64,${media.base64}`;
    } catch (err) {
      console.error(err);
    }
  };

  const handleApplyRelight = useCallback(async () => {
    if (!sourceMedia || !activeVector || isLoading) return;

    setIsLoading(true);
    setError(null);

    const dx = activeVector.end.x - activeVector.start.x;
    const dy = activeVector.end.y - activeVector.start.y;
    const distance = Math.sqrt(dx * dx + dy * dy);

    let direction = "center";
    if (Math.abs(dx) > Math.abs(dy)) {
      direction = dx > 0 ? "from the left, casting shadows to the right" : "from the right, casting shadows to the left";
    } else {
      direction = dy > 0 ? "from above, casting shadows downwards" : "from below, casting shadows upwards";
    }

    const lightingHardness = distance > 0.4 ? "hard, directional beam casting long dramatic shadows" : "soft, diffused glow";
    const sourcePos = `positioned at relative coordinates (${Math.round(activeVector.start.x * 100)}%, ${Math.round(activeVector.start.y * 100)}%)`;

    const prompt = `A professional ${lightStyle.toLowerCase()} relighting. A ${lightingHardness} of ${lightColor.toLowerCase()} light ${sourcePos}, shining ${direction}. High contrast, ${intensity}% intensity, cinematic atmosphere. Maintain all original subjects and geometry exactly.`;

    try {
      const result = await Flow.generate.image({
        prompt,
        modelDisplayName: model,
        referenceImageMediaIds: [sourceMedia.mediaId],
        aspectRatio: detectedRatio,
      });
      setResultMedia(result);
      setActiveVector(null); // Clear placement after successful generation
    } catch (err: any) {
      setError(err.message || "Relighting failed. Try again.");
    } finally {
      setIsLoading(false);
    }
  }, [sourceMedia, activeVector, isLoading, lightStyle, lightColor, intensity, model, detectedRatio]);

  const handleReset = () => {
    setResultMedia(null);
    setActiveVector(null);
    setError(null);
  };

  return (
    <div className="flex h-screen w-screen bg-[#0e0e0e] overflow-hidden">
      <SettingsPanel 
        model={model} setModel={setModel}
        lightStyle={lightStyle} setLightStyle={setLightStyle}
        intensity={intensity} setIntensity={setIntensity}
        lightColor={lightColor} setLightColor={setLightColor}
        onSelect={handleSelectMedia}
        onReset={handleReset}
        onApply={handleApplyRelight}
        hasSource={!!sourceMedia}
        activeVector={activeVector}
        isLoading={isLoading}
        detectedRatio={detectedRatio}
      />

      <div className="flex-1 relative flex items-center justify-center p-8">
        {error && (
          <div className="absolute top-4 left-1/2 -translate-x-1/2 z-20 px-4 py-2 bg-red-500/20 border border-red-500/40 rounded-xl backdrop-blur-md">
            <span className="text-red-400 text-xs font-medium">{error}</span>
          </div>
        )}

        <LightCanvas 
          source={sourceMedia} 
          result={resultMedia} 
          activeVector={activeVector}
          onVectorChange={setActiveVector}
          isLoading={isLoading}
        />

        {!sourceMedia && !isLoading && (
          <div className="flex flex-col items-center gap-4 animate-in fade-in duration-700">
            <div className="w-16 h-16 rounded-full bg-white/5 flex items-center justify-center border border-white/10">
              <span className="material-symbols-outlined text-white/40 text-[32px]">photo_camera</span>
            </div>
            <div className="text-center">
              <h2 className="text-white font-medium text-lg tracking-tight">Luminary</h2>
              <p className="text-white/40 text-sm max-w-[240px]">Select a scene to start relighting with AI</p>
            </div>
            <button 
              onClick={handleSelectMedia}
              className="mt-2 h-[34px] px-6 rounded-xl bg-white text-black text-xs font-medium hover:bg-gray-200 transition-all cursor-pointer"
            >
              Select Image
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { SectionLabel, PillButton, FieldDropdown, RangeSlider } from './Primitives';
import { LightVector } from '../App';

interface SettingsPanelProps {
  model: string;
  setModel: (v: string) => void;
  lightStyle: string;
  setLightStyle: (v: string) => void;
  intensity: number;
  setIntensity: (v: number) => void;
  lightColor: string;
  setLightColor: (v: string) => void;
  onSelect: () => void;
  onReset: () => void;
  onApply: () => void;
  hasSource: boolean;
  activeVector: LightVector | null;
  isLoading: boolean;
  detectedRatio: string;
}

const MODELS = ['🍌 Nano Banana Pro', '🍌 Nano Banana 2', '🍌 Nano Banana 2 Lite'];
const STYLES = ['Cinematic', 'Neon / Cyberpunk', 'Golden Hour', 'Studio', 'Soft Diffusion', 'Noir / Moody'];
const COLORS = ['Warm White', 'Cool Blue', 'Vibrant Pink', 'Toxic Green', 'Golden Amber', 'Deep Red', 'Daylight'];

export const SettingsPanel: React.FC<SettingsPanelProps> = ({
  model, setModel,
  lightStyle, setLightStyle,
  intensity, setIntensity,
  lightColor, setLightColor,
  onSelect, onReset, onApply,
  hasSource, activeVector, isLoading,
  detectedRatio
}) => {
  // Credits for image models in Ultra are usually 0 or included.
  const creditCost = 0; 

  return (
    <div className="relative border-r border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-clip px-[10px] py-[12px] w-[300px] h-full min-h-0 bg-[#0e0e0e] z-10">
      <div className="flex flex-col gap-[24px] items-start w-full">

        {/* Source Management */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Scene</SectionLabel>
          <div className="flex flex-col gap-1.5 w-full">
            <div className="flex gap-1 w-full">
              <PillButton 
                icon={<span className="material-symbols-outlined text-[18px]">add_photo_alternate</span>} 
                variant="filled"
                onClick={onSelect}
                disabled={isLoading}
              >
                {hasSource ? 'Replace' : 'Upload'}
              </PillButton>
              {hasSource && (
                <PillButton 
                  icon={<span className="material-symbols-outlined text-[18px]">restart_alt</span>} 
                  variant="outline"
                  onClick={onReset}
                  disabled={isLoading}
                >
                  Reset
                </PillButton>
              )}
            </div>
          </div>
        </div>

        {/* Model Selection */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Intelligence</SectionLabel>
          <FieldDropdown 
            label="AI Model" 
            value={model} 
            options={MODELS} 
            onChange={setModel} 
            className="w-full" 
          />
        </div>

        {/* Lighting Parameters */}
        <div className="flex flex-col gap-2 items-start w-full">
          <SectionLabel>Lighting Engine</SectionLabel>
          <div className="flex flex-col gap-1.5 w-full">
            <FieldDropdown 
              label="Atmosphere" 
              value={lightStyle} 
              options={STYLES} 
              onChange={setLightStyle} 
            />
            <FieldDropdown 
              label="Tone / Color" 
              value={lightColor} 
              options={COLORS} 
              onChange={setLightColor} 
            />
            <RangeSlider 
              label="Source Intensity" 
              value={intensity} 
              min={10} max={100} 
              formatValue={(v) => `${v}%`}
              onChange={setIntensity} 
            />
          </div>
        </div>

        {hasSource && !activeVector && !isLoading && (
          <div className="px-3 py-4 rounded-xl bg-white/5 border border-white/5 w-full">
            <p className="text-[10px] text-white/40 leading-relaxed italic flex items-center gap-2">
              <span className="material-symbols-outlined text-[14px]">gesture</span>
              Drag on the image to place a light source.
            </p>
          </div>
        )}

        {activeVector && !isLoading && (
          <div className="flex flex-col gap-3 w-full animate-in slide-in-from-bottom-2 duration-300">
            <div className="h-px bg-white/10 w-full" />
            <div className="flex items-center justify-between px-2">
              <span className="text-[11px] text-white/40 font-medium">Estimated Usage</span>
              <div className="flex items-center gap-1.5">
                <span className="text-[11px] text-white font-bold">{creditCost} Credits</span>
                <span className="px-1.5 py-0.5 rounded-sm bg-green-500/20 text-green-400 text-[8px] font-black uppercase tracking-widest">Free</span>
              </div>
            </div>
            <PillButton 
              variant="solid" 
              onClick={onApply}
              icon={<span className="material-symbols-outlined text-[18px]">bolt</span>}
            >
              Apply Relight
            </PillButton>
          </div>
        )}
      </div>

      <div className="w-full pt-4 border-t border-white/10 mt-auto">
        <div className="flex items-center justify-between px-2">
          <div className="flex items-center gap-2">
            <div className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-amber-500 animate-pulse' : 'bg-green-500'}`} />
            <span className="text-[10px] text-white/40 uppercase tracking-widest font-bold">
              {isLoading ? 'Processing...' : 'Ready'}
            </span>
          </div>
          {hasSource && (
            <span className="text-[10px] text-white/20 font-bold">{detectedRatio}</span>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { LightVector } from '../App';

interface LightCanvasProps {
  source: any;
  result: any;
  activeVector: LightVector | null;
  onVectorChange: (v: LightVector | null) => void;
  isLoading: boolean;
}

export const LightCanvas: React.FC<LightCanvasProps> = ({ 
  source, 
  result, 
  activeVector,
  onVectorChange, 
  isLoading 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState<{ x: number; y: number } | null>(null);
  const [dragCurrent, setDragCurrent] = useState<{ x: number; y: number } | null>(null);

  const getRelativeCoords = useCallback((clientX: number, clientY: number) => {
    if (!containerRef.current) return { x: 0, y: 0 };
    const rect = containerRef.current.getBoundingClientRect();
    return {
      x: (clientX - rect.left) / rect.width,
      y: (clientY - rect.top) / rect.height
    };
  }, []);

  const handleMouseUp = useCallback(() => {
    if (!isDragging || !dragStart || !dragCurrent || isLoading) {
      setIsDragging(false);
      return;
    }

    // Check if it was a meaningful drag (not just a tiny jitter)
    const dx = dragCurrent.x - dragStart.x;
    const dy = dragCurrent.y - dragStart.y;
    const dist = Math.sqrt(dx * dx + dy * dy);

    if (dist > 0.01) {
      onVectorChange({
        start: dragStart,
        end: dragCurrent
      });
    }

    setIsDragging(false);
    setDragStart(null);
    setDragCurrent(null);
  }, [isDragging, dragStart, dragCurrent, isLoading, onVectorChange]);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mouseup', handleMouseUp);
      return () => window.removeEventListener('mouseup', handleMouseUp);
    }
  }, [isDragging, handleMouseUp]);

  if (!source) return null;

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isLoading) return;
    const coords = getRelativeCoords(e.clientX, e.clientY);
    setDragStart(coords);
    setDragCurrent(coords);
    setIsDragging(true);
    // Clear any previous finalized vector when starting a new drag
    onVectorChange(null);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging || isLoading) return;
    setDragCurrent(getRelativeCoords(e.clientX, e.clientY));
  };

  const displayUrl = result 
    ? `data:${result.mimeType};base64,${result.base64}` 
    : `data:${source.mimeType};base64,${source.base64}`;

  // Current drawing state (either active drag or finalized vector)
  const vizVector = isDragging && dragStart && dragCurrent 
    ? { start: dragStart, end: dragCurrent }
    : activeVector;

  return (
    <div 
      ref={containerRef}
      className={`relative max-w-full max-h-full aspect-auto rounded-2xl overflow-hidden shadow-2xl border border-white/10 transition-all duration-500 ${isLoading ? 'opacity-70 scale-[0.98]' : 'hover:shadow-white/5'} cursor-crosshair group select-none`}
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
    >
      <img 
        src={displayUrl} 
        alt="Scene" 
        className="max-w-full max-h-[80vh] object-contain block select-none pointer-events-none"
      />

      {isLoading && (
        <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-[2px] z-30">
          <div className="flex flex-col items-center gap-3">
            <div className="w-8 h-8 border-2 border-white/20 border-t-white rounded-full animate-spin" />
            <span className="text-white text-[10px] font-bold tracking-widest uppercase">Relighting...</span>
          </div>
        </div>
      )}

      {/* Vector Visualization (Drag or Finalized) */}
      {vizVector && (
        <svg className="absolute inset-0 w-full h-full pointer-events-none z-20 overflow-visible">
          <defs>
            <filter id="glow">
              <feGaussianBlur stdDeviation="3" result="blur" />
              <feComposite in="SourceGraphic" in2="blur" operator="over" />
            </filter>
          </defs>
          <line 
            x1={`${vizVector.start.x * 100}%`} 
            y1={`${vizVector.start.y * 100}%`} 
            x2={`${vizVector.end.x * 100}%`} 
            y2={`${vizVector.end.y * 100}%`} 
            stroke="white" 
            strokeWidth={isDragging ? "2" : "3"} 
            strokeDasharray={isDragging ? "4 2" : "0"}
            filter="url(#glow)"
            className={`${isDragging ? 'opacity-80' : 'opacity-100'} transition-opacity`}
          />
          <circle 
            cx={`${vizVector.start.x * 100}%`} 
            cy={`${vizVector.start.y * 100}%`} 
            r="8" 
            fill="white" 
            filter="url(#glow)"
          />
          <circle 
            cx={`${vizVector.end.x * 100}%`} 
            cy={`${vizVector.end.y * 100}%`} 
            r="4" 
            fill="white" 
            className="opacity-50"
          />
        </svg>
      )}

      {!isLoading && !vizVector && (
        <div className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10">
          <div className="absolute inset-0 bg-white/5" />
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex flex-col items-center">
            <span className="material-symbols-outlined text-white/50 text-[48px]">flare</span>
            <span className="text-white/50 text-[10px] font-medium tracking-tight mt-1 uppercase">Drag to set light source</span>
          </div>
        </div>
      )}

      {/* Visual Indicator Labels */}
      <div className="absolute bottom-4 left-4 flex gap-2 z-10">
        <div className={`px-2 py-1 rounded bg-black/60 backdrop-blur-md border border-white/10 text-[9px] font-bold tracking-tighter text-white/80 uppercase`}>
          {result ? 'AI RELIGHT' : 'ORIGINAL SCENE'}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] normal-case">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[2px] justify-center w-full h-[34px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] pl-[8px] pr-[24px] py-1 select-none',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 backdrop-blur-[40px] text-[12px] pl-[8px] pr-[16px] py-2 text-white select-none',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[12px] pl-[8px] pr-[16px] py-2 select-none',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center w-6 h-6">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

function useOnClickOutside(ref: React.RefObject<HTMLElement | null>, handler: (e: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) return;
      handler(event);
    };
    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);
    return () => { document.removeEventListener('mousedown', listener); document.removeEventListener('touchstart', listener); };
  }, [ref, handler]);
}

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useOnClickOutside(ref, () => setIsOpen(false));

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button 
        type="button" 
        onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-2.5 pr-1 pt-[5px] select-none focus:outline-none bg-transparent"
      >
        <p className="text-[11px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.1px]">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px] truncate mr-2">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] mr-1 transition-transform ${isOpen ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#0e0e0e] border border-[#595959] rounded-xl overflow-hidden shadow-xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-2.5 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-[#1a1a1a] transition-colors ${value === opt ? 'bg-[#1a1a1a] text-white' : 'text-[rgba(218,220,224,0.9)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const RangeSlider: React.FC<{
  label: string; 
  value: number; 
  min: number; 
  max: number;
  step?: number; 
  formatValue?: (val: number) => string;
  onChange: (val: number) => void;
}> = ({ label, value, min, max, step = 1, formatValue = (v) => String(v), onChange }) => (
  <div className="flex flex-col gap-2 pt-2 pb-[5px] w-full">
    <div className="flex items-center justify-between px-2 select-none">
      <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px]">{label}</span>
      <span className="text-[11px] font-medium text-[#c7c9cd] tracking-[0.1px]">{formatValue(value)}</span>
    </div>
    <div className="px-2 w-full flex items-center h-2">
      <input type="range" min={min} max={max} step={step} value={value}
        onChange={(e) => onChange(Number(e.target.value))} />
    </div>
  </div>
);
